{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C03"],
      "claim": "The closest scaffold analogue, a fused heteroaromatic with an aminoaryl group and piperidine substituent, has a predicted human absolute oral bioavailability of ~70% at <15 mg; its very high transfer score (0.9909) strongly supports high F for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C05"],
      "claim": "Alizapride, a methoxy-substituted heteroaromatic with a basic piperidine, had absolute systemic availability of 72.5 ± 14.8% after oral dosing in humans; this high-transfer human measurement supports high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C21"],
      "claim": "Tramadol, a methoxyphenyl amino alcohol, had mean absolute oral bioavailability of 67.9% in adult volunteers after a 100 mg oral dose; high-transfer evidence supports high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C39"],
      "claim": "Naproxen, a methoxy-substituted aromatic drug, has absolute oral bioavailability of 99% in humans; although acidic and less structurally similar, it confirms that methoxyaryl-containing drugs can be highly bioavailable.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C34"],
      "claim": "Ranolazine (retrieved record) has oral bioavailability of 35–50% in humans, above the 20% threshold; despite limited structural similarity, it is consistent with high F.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "All high-transfer human bioavailability records for structurally relevant analogues are ≥20%, with the closest scaffold analogue ~70%; no affirmative threshold-relevant evidence supports low F. Therefore predict high.",
  "evidence_gaps": [
    "No direct absolute oral bioavailability measurement for the query molecule itself.",
    "One key analogue (ZL-2201) is a predicted rather than measured human F.",
    "Some records are unspecified bioavailability type or dose/disease-dependent (encainide, rivastigmine)."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

